// Battle-local visual queue. State resolves once; snapshots remain valid after evolution.
function canPresentBattleCards(){return !globalThis.ASHBOUND_HEADLESS&&typeof document.createElement==='function'&&typeof document.body.append==='function';}
const battlePresentations=[];let battlePresentationPromise=null,battlePresentationWait=null,battlePresentationSkip=false,battlePresentationHost=null;
function presentationSnapshot(id){return card(id).replace(/\b(?:unplayable|playable|empowered)\b/g,'').replace('<button ','<button tabindex="-1" ');}
function startBattlePresentations(){if(battlePresentationPromise||!battlePresentations.length)return;battlePresentationPromise=drainBattlePresentations().catch(()=>{battlePresentations.length=0;battlePresentationHost?.remove();battlePresentationHost=null;}).finally(()=>{battlePresentationPromise=null;if(page==='battle')startBattlePresentations();else battlePresentations.length=0;});}
function enqueueBattlePresentation(event){if(!canPresentBattleCards()||page!=='battle')return;battlePresentations.push(event);startBattlePresentations();}
function queuePlayedCardPresentation(r,id){if(!canPresentBattleCards())return;try{enqueueBattlePresentation({run:r,kind:'play',front:presentationSnapshot(id),name:C[id].name});}catch{/* Visual failures must never stop a card from resolving. */}}
const evolvePresentationBase=evolveCardInstance;evolveCardInstance=function(r,id,reverse=false){let before=null;try{if(canPresentBattleCards()&&!reverse)before=presentationSnapshot(id);}catch{}const next=evolvePresentationBase(r,id,reverse);try{if(before&&next!==id)enqueueBattlePresentation({run:r,kind:'evolve',front:before,back:presentationSnapshot(next),name:C[id].name+' → '+C[next].name});}catch{}return next;};
function waitBattlePresentation(ms){return new Promise(resolve=>{const timer=setTimeout(()=>{battlePresentationWait=null;resolve();},ms);battlePresentationWait=()=>{clearTimeout(timer);battlePresentationWait=null;resolve();};});}
function skipBattlePresentations(){battlePresentationSkip=true;battlePresentations.length=0;battlePresentationWait?.();battlePresentationHost?.remove();}
function positionBattlePresentation(){const host=battlePresentationHost?.querySelector('.presentation-anchor');if(!host?.style||page!=='battle')return;const arena=document.querySelector('.arena'),rect=arena?.getBoundingClientRect?.();host.style.left=(rect?rect.left+rect.width/2:window.innerWidth/2)+'px';host.style.top=(rect?rect.top+rect.height/2:window.innerHeight/2)+'px';}
async function drainBattlePresentations(){battlePresentationSkip=false;const dialog=document.createElement('div');dialog.className='battle-presentation';battlePresentationHost=dialog;dialog.setAttribute('role','region');dialog.setAttribute('aria-label','カードの使用・進化');dialog.innerHTML='<div class="presentation-anchor"><div class="presentation-stage" aria-live="polite"></div></div>';document.body.append(dialog);positionBattlePresentation();try{while(battlePresentations.length&&!battlePresentationSkip){const event=battlePresentations.shift();if(S.run!==event.run||page!=='battle')continue;const stage=dialog.querySelector('.presentation-stage');stage.classList?.remove('is-leaving');positionBattlePresentation();stage.innerHTML='<div class="presentation-caption">'+(event.kind==='evolve'?'進化':'カードをプレイ')+'</div><div class="presentation-card-space"><div class="presentation-flipper '+(event.kind==='evolve'?'is-evolving':'is-playing')+'"><div class="presentation-front">'+event.front+'</div>'+(event.back?'<div class="presentation-back">'+event.back+'</div>':'')+'</div></div><div class="presentation-name">'+event.name+'</div>';const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;await waitBattlePresentation(reduced?140:1000);if(battlePresentationSkip)break;if(event.kind==='evolve'&&!reduced)await waitBattlePresentation(500);if(battlePresentationSkip)break;stage.classList?.add('is-leaving');await waitBattlePresentation(reduced?80:450);}}finally{dialog.remove();if(battlePresentationHost===dialog)battlePresentationHost=null;}}
// Visual playback never delays combat, choices, victory or defeat.
const renderPresentationBase=render;render=function(){if(globalThis.ASHBOUND_LOADING)return;renderPresentationBase();if(page!=='battle'||!S.run)skipBattlePresentations();else positionBattlePresentation();};
window.addEventListener('resize',positionBattlePresentation);window.addEventListener('scroll',positionBattlePresentation,true);
if(!globalThis.ASHBOUND_HEADLESS)render();
